+                for (String masterAddr : masterSet) {
+                    UserInfo userInfo = defaultMQAdminExt.getUser(masterAddr, username);
+                    if (userInfo != null) {
+                        printUser(userInfo);
+                        break;
+                    }
+                }
+
+                return;
+            }
