+                    return;
+                }
+                entries.forEach(entry -> {
+                    System.out.printf(FORMAT, acl.getSubject(), policy.getPolicyType(), entry.getResource(),
+                        entry.getActions(), entry.getSourceIps(), entry.getDecision());
+                });
+            });
+        });
+    }
