+    public int compareTo(PolicyEntry o) {
+        int compare = this.resource.compareTo(o.getResource());
+        if (compare != 0) {
+            return compare;
+        }
+        // the decision deny has higher priority
+        return this.decision == Decision.DENY ? 1 : o.decision == Decision.DENY ? -1 : 0;
