+        if (keySet == null || keySet.isEmpty()) {
+            return AppendResult.SUCCESS;
+        }
+
+        try {
+            fileReadWriteLock.writeLock().lock();
+
+            if (!UNSEALED.equals(fileStatus.get())) {
