+                int slotPosition = this.getSlotPosition(hashCode % this.hashSlotMaxCount);
+                int slotOldValue = this.getSlotValue(slotPosition);
+                int timeDiff = (int) ((timestamp - this.beginTimestamp.get()) / 1000L);
