+                    itemBuffer.get(bytes);
+                    IndexItem indexItem = new IndexItem(bytes);
+                    long storeTimestamp = indexItem.getTimeDiff() + beginTimestamp.get();
+                    if (hashCode == indexItem.getHashCode() &&
